r.gaps = rec.gaps; r.statement_missing = rec.statement_missing; r.files = rec.files; r.parse_errors = rec.errors;
if (rec.gaps.length) r.lines.push(rec.gaps.length + ' bank alert(s) have no statement line after 2 days. Check them before trusting those payments.');
