  const render = w.add('n8n-nodes-base.code', 'Render tier cards, checkout, templates', code(`
const rows = BILLING.pricing.validateRows($('Load pricing').first().json.rows);
// smc_pricing_notify (06) fires on EVERY pricing write, including our own Paystack-code write-back below.
// A LISTEN-triggered run whose price-relevant fields are unchanged since the last publish is a no-op (no loop).
const sd = $getWorkflowStaticData('global');
const SKIP = new Set(['paystack_page_code', 'paystack_plan_code', 'created_at', 'updated_at']);
const sig = JSON.stringify(rows.map((r) => Object.keys(r).sort().filter((k) => !SKIP.has(k)).map((k) => [k, r[k]])));
let fromListen = false; try { fromListen = $('pricing row changed (LISTEN)').isExecuted; } catch (e) { fromListen = false; }
if (fromListen && sd.publishedSig === sig) return [];
sd.publishedSig = sig;
const staging = String($env.W25_TARGET || 'staging') !== 'production';
const opts = { includeUnapproved: staging };
const live = BILLING.pricing.activeRows(rows, opts);
if (!live.length) throw new Error('W25: no approved pricing rows (active_from) - nothing to publish to production');
sd.pricingRows = rows;
const cards = BILLING.render.renderTierCards(rows, { ...opts, checkoutUrl: 'https://app.leadvelocity.co.za/billing/checkout/' });
const tplHtml = Buffer.from($input.first().binary.data.data, 'base64').toString('utf8');
const esc = (s) => s.replace(/&/g, '&amp;').replace(/'/g, '&#39;');
const checkout = tplHtml.replace("'{{PRICING_JSON}}'", "'" + esc(BILLING.render.checkoutPricingJson(rows, opts)) + "'")
  .replace('{{BILLING_API_BASE}}', $env.BILLING_API_BASE || '').replace('{{BANK_NAME}}', $env.BANK_NAME || '').replace('{{BANK_ACCOUNT_NAME}}', $env.BANK_ACCOUNT_NAME || '')
  .replace('{{BANK_ACCOUNT_NUMBER}}', $env.BANK_ACCOUNT_NUMBER || '').replace('{{BANK_BRANCH_CODE}}', $env.BANK_BRANCH_CODE || '').replace('{{BANK_ACCOUNT_TYPE}}', $env.BANK_ACCOUNT_TYPE || '')
  .replace('../../brand/tokens.css', 'tokens.css');
const templates = Object.fromEntries(live.map((r) => [r.tier_code, { proposal_block: BILLING.render.proposalTierBlock(r), schedule_a: BILLING.render.scheduleAVars(r) }]));
const files = [
  { path: 'pricing/tier-cards.html', content: cards },
  { path: 'billing/checkout/index.html', content: checkout },
  { path: 'templates/pricing-templates.json', content: JSON.stringify(templates, null, 2) },
  { path: 'pricing/pricing.json', content: BILLING.render.checkoutPricingJson(rows, opts) },
];
const paystack = live.flatMap((r) => [{ tier_code: r.tier_code, kind: 'page', spec: BILLING.paystack.build.paymentPage(r, { redirectUrl: 'https://app.leadvelocity.co.za/billing/checkout/thanks' }) },
  { tier_code: r.tier_code, kind: 'plan', spec: BILLING.paystack.build.plan(r) }]);
return [{ json: { staging, files, paystack } }];
`, ['pricing', 'render', 'paystack']), { v: 2, row: 0, col: 3 });
  const diff = w.add('n8n-nodes-base.executeCommand', 'Diff check: no hard-coded price in the repo', { command: "={{ 'cd ' + ($env.REPO_DIR || '/home/node/repo') + ' && git pull --ff-only -q && node automation/billing/price-diff.mjs --json' }}" }, { v: 1, row: 0, col: 4, onError: 'continueRegularOutput' });
